def gen(rng):
    def serialize(vals, left, right):
        out = [str(vals[0])]
        q = [0]
        h = 0
        while h < len(q):
            u = q[h]
            h += 1
            for ch in (left[u], right[u]):
                if ch == -1:
                    out.append('null')
                else:
                    out.append(str(vals[ch]))
                    q.append(ch)
        while out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def build(n, kind, vr):
        vals = [rng.randint(-vr, vr) for _ in range(n)]
        left = [-1] * n
        right = [-1] * n
        if kind == 'random':
            free = [(0, 0), (0, 1)]
            for v in range(1, n):
                idx = rng.randrange(len(free))
                free[idx], free[-1] = free[-1], free[idx]
                u, s = free.pop()
                if s == 0:
                    left[u] = v
                else:
                    right[u] = v
                free.append((v, 0))
                free.append((v, 1))
        elif kind == 'left':
            for i in range(n - 1):
                left[i] = i + 1
        elif kind == 'right':
            for i in range(n - 1):
                right[i] = i + 1
        elif kind == 'zigzag':
            for i in range(n - 1):
                if i % 2 == 0:
                    left[i] = i + 1
                else:
                    right[i] = i + 1
        elif kind == 'complete':
            for i in range(n):
                if 2 * i + 1 < n:
                    left[i] = 2 * i + 1
                if 2 * i + 2 < n:
                    right[i] = 2 * i + 2
        return serialize(vals, left, right)

    tests = ['7', '1 2 3 null 6 5', '10 5 15 3 7 12 18 1', '4 null 8 null 2', '3 3 3 3 3 3 3', '1 null 2 3', '-5 -5']
    for n in (2, 3, 4, 5, 7, 9, 12, 16, 20):
        for kind in ('random', 'random', 'complete'):
            tests.append(build(n, kind, 3))
    for kind in ('left', 'right', 'zigzag'):
        tests.append(build(15, kind, 5))
    N = 10**5
    tests.append(build(N, 'random', 10**6))
    tests.append(build(N, 'complete', 3))
    tests.append(build(N, 'left', 10**6))
    tests.append(build(N, 'zigzag', 10**6))
    tests.append(build(N, 'random', 4))
